pm.test("[Data] Berisi array list hero dan set variable heroId", function () {
    var j = pm.response.json();
    pm.expect(j.data).to.be.an('array').that.is.not.empty;
    var hero = j.data[0];
    var id = hero.hero_id || hero.id;
    if (id) {
        pm.collectionVariables.set("heroId", String(id));
    }
});

