pm.test("[Data] Menyimpan playerId ke variable", function () {
    var j = pm.response.json();
    pm.expect(j.data).to.be.an('array').that.is.not.empty;
    var p1 = j.data[0];
    var id1 = p1.player_id || p1.id;
    if (id1) {
        pm.collectionVariables.set("playerId", String(id1));
    }
    if (j.data.length > 1) {
        var p2 = j.data[1];
        var id2 = p2.player_id || p2.id;
        if (id2) {
            pm.collectionVariables.set("player2Id", String(id2));
        }
    }
});

